"544 :     private T processProperty(
545 :         NodeTraversal t, Property prop, T type, T relatedType) {
546 :       type = typeSystem.restrictByNotNullOrUndefined(type);
547 :       if (prop.skipRenaming || typeSystem.isInvalidatingType(type)) {
548 :         return null;
549 :       }
550 : 
551 :       Iterable<T> alternatives = typeSystem.getTypeAlternatives(type);
552 :       if (alternatives != null) {
553 :         T firstType = relatedType;
554 :         for (T subType : alternatives) {
555 :           T lastType = processProperty(t, prop, subType, firstType);
556 :           if (lastType != null) {
557 :             firstType = firstType == null ? lastType : firstType;
558 :           }
559 :         }
560 :         return firstType;
561 :       } else {
562 :         T topType = typeSystem.getTypeWithProperty(prop.name, type);
563 :         if (typeSystem.isInvalidatingType(topType)) {
564 :           return null;
565 :         }
566 :         prop.addType(type, topType, relatedType);
567 :         return topType;
568 :       }
569 :     }"

