"627 :   private Map<T, String> buildPropNames(UnionFind<T> types, String name) {
628 :     Map<T, String> names = Maps.newHashMap();
629 :     for (Set<T> set : types.allEquivalenceClasses()) {
630 :       checkState(!set.isEmpty());
631 : 
632 :       String typeName = null;
633 :       for (T type : set) {
634 :         if (typeName == null || type.toString().compareTo(typeName) < 0) {
635 :           typeName = type.toString();
636 :         }
637 :       }
638 : 
639 :       String newName;
640 :       if ("{...}".equals(typeName)) {
641 :         newName = name;
642 :       } else {
643 :         newName = typeName.replaceAll("[^\\w$]", "_") + "$" + name;
644 :       }
645 : 
646 :       for (T type : set) {
647 :         names.put(type, newName);
648 :       }
649 :     }
650 :     return names;
651 :   }"

